function showBattle(b){if(!b)return;activeInfo=null;activeFaction=null;activeBattle=b;activeArmy=null;previewDestination='';clearReach();const zh=lang==='zh',side=(id)=>{const v=battleSideForPlayer(b,state.player,id),title=id==='attacker'?(zh?'进攻方':'ATTACKER'):(zh?'防守方':'DEFENDER');return `<div>${factionMark(v.owner,'insignia')}<small>${title}</small>${v.unknown?`<strong>${zh?'对方部队':'Opposing force'}</strong><span>${zh?'指挥官与确切兵力未知':'Commander and exact strength unknown'}</span><span>${zh?'粮食、战力与伤亡未知':'Food, power and casualties unknown'}</span>`:`<strong>${esc(n(v.commander))}</strong><span>${v.men.toLocaleString()} · ${t('morale')} ${v.morale}</span><span>${t('food')} ${v.food} · ${zh?'战力':'power'} ${v.power}</span><b>−${v.casualties.toLocaleString()}</b>`}</div>`};inspect(zh?'战斗报告':'BATTLE REPORT',`${n(region(state,b.region).name)} · ${zh?(b.attackerWins?'进攻方获胜':'防守方获胜'):(b.attackerWins?'Attacker victory':'Defender victory')}`);document.querySelector('#command-detail').innerHTML=`<div class="battle-columns">${side('attacker')}${side('defender')}</div><p class="battle-note">${zh?'战场地形':'Battlefield terrain'}: ${terrainName(b.terrain)} · ${zh?'工事':'Fortifications'}: ${b.fort}</p><p class="battle-note">${zh?'敌方具体数据未经核实；战斗根据双方状态、地形和随机因素结算。':'Specific enemy details are unverified; battles account for each side’s condition, terrain and chance.'}</p>`;emit('battle')}
