function zoomClass(){document.body.classList.toggle('low-zoom',map.getZoom()<5.2);document.body.classList.toggle('leader-overview',map.getZoom()<4.8)}map.on('zoom',zoomClass);zoomClass();
document.querySelector('#relief-toggle').onclick=()=>{reliefEnabled=!reliefEnabled;localStorage.setItem('spqr-relief',reliefEnabled?'on':'off');if(map.getLayer('relief'))map.setLayoutProperty('relief','visibility',reliefEnabled?'visible':'none');renderHud()};
document.querySelector('#zoom-in').onclick=()=>map.zoomIn();document.querySelector('#zoom-out').onclick=()=>map.zoomOut();document.querySelector('#reset').onclick=()=>map.flyTo({center:[12.4,43.2],zoom:5.45});

function advanceTurn(){
 const before={treasury:state.factions[state.player].treasury,food:state.factions[state.player].food,owners:Object.fromEntries(state.regions.map(r=>[r.id,r.owner])),armies:Object.fromEntries(state.armies.map(a=>[a.id,{region:a.region,move:a.move?.to}]))};
 tick(state);const changes=state.regions.filter(r=>before.owners[r.id]!==r.owner).map(r=>({name:r.name,owner:FACTIONS[r.owner].short}));const movements=state.armies.filter(a=>a.owner===state.player&&before.armies[a.id]&&before.armies[a.id].region!==a.region).map(a=>({owner:a.owner,name:a.name,to:region(state,a.region).name}));const delta={treasury:state.factions[state.player].treasury-before.treasury,food:state.factions[state.player].food-before.food};(state.turnSummaries||=[]).unshift({year:state.year,month:state.month,delta,changes,movements,events:state.log.filter(e=>e.month===state.month&&e.year===state.year).slice(0,12)});state.turnSummaries=state.turnSummaries.slice(0,24);renderArmies();
 const battles=state.log.filter(e=>e.month===state.month&&e.year===state.year&&e.en.includes('Casualties:'));
 for(const event of battles){const r=state.regions.find(x=>event.en.includes('at '+x.name[0]+'.'));if(!r||!namedPoints[r.id])continue;const icon=document.createElement('button');icon.className='battle-indicator';icon.title=lang==='zh'?'查看战斗报告':'Inspect battle report';icon.setAttribute('aria-label',icon.title);icon.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3l14 14m2-14L6 17M2 6l4-4m12 0l4 4M4 15l5 5m6 0l5-5"/></svg>';icon.onclick=e=>{e.stopPropagation();const b=state.battles?.find(x=>x.region===r.id&&x.month===state.month&&x.year===state.year&&(x.attacker.owner===state.player||x.defender.owner===state.player));if(b)showBattle(b);else inspect(lang==='zh'?'战斗报告':'Battle report',lang==='zh'?event.zh:event.en)};const m=marker(icon,namedPoints[r.id]);battleMarkers.push(m);setTimeout(()=>{m.remove();battleMarkers=battleMarkers.filter(x=>x!==m)},10000)}
 const current=state.armies.find(a=>a.id===activeArmy&&a.owner===state.player)||reportedArmies(state,state.player).find(a=>a.id===activeArmy);if(current)showArmy(current);else clearReach();renderHud();renderLeaders();if(activeFaction)showFaction(activeFaction,factionSection);else if(activeInfo?.type==='character')characterUI.show(activeInfo.id);else if(activeInfo?.type==='road')showRoad(activeInfo.name);else if(activeInfo?.type==='city'){const selected=cities.find(c=>c.name===activeInfo.name);if(selected)showCity(selected)}else if(activeInfo?.type==='region')showRegion(region(state,activeInfo.id));if(state.log.length){const e=state.log[0];const actor=Object.keys(FACTIONS).find(id=>e.en.startsWith(FACTIONS[id].short[0]+' '))||state.armies.find(a=>e.en.startsWith(a.name[0]+' '))?.owner;status.innerHTML=(actor?factionMark(actor,'insignia'):'')+`<span>${esc(visibleLogText(e,lang))}</span>`;status.style.display='flex';setTimeout(()=>status.style.display='none',5000)}const summary=state.turnSummaries[0];status.innerHTML=`<span>${lang==='zh'?'本月结算':'MONTHLY SUMMARY'} · ${lang==='zh'?'国库':'Treasury'} ${delta.treasury>=0?'+':''}${delta.treasury} · ${lang==='zh'?'粮食':'Food'} ${delta.food>=0?'+':''}${delta.food}<br>${summary.movements.length} ${lang==='zh'?'支军队抵达':'armies arrived'} · ${summary.changes.length} ${lang==='zh'?'处控制权变化':'control changes'} · ${lang==='zh'?'详情见战报':'see Chronicle'}</span>`;status.style.display='flex';const battle=(state.battles||[]).some(b=>b.month===state.month&&b.year===state.year&&(b.attacker.owner===state.player||b.defender.owner===state.player));if(battle&&playing)setPlaying(false);emit('advance','',{battle});
}
document.querySelector('#advance').onclick=advanceTurn;
function setPlaying(on){if(timer)clearInterval(timer);timer=null;playing=on;if(on)timer=setInterval(advanceTurn,speed===1?2000:speed===2?1000:500);renderHud()}
document.querySelector('#play-time').onclick=()=>setPlaying(!playing);document.querySelector('#time-speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;if(playing)setPlaying(true);else renderHud()};

document.querySelector('#return-campaign').onclick=e=>{e.preventDefault();try{stageHandoff(sessionStorage,state,'campaign');setPlaying(false);location.assign('../')}catch{status.textContent=lang==='zh'?'无法切换：浏览器未能暂存战役，请检查存储设置。':'Could not transfer the campaign. Check browser storage settings.';status.style.display='block'}};
document.querySelector('#language').onclick=()=>{lang=lang==='en'?'zh':'en';localStorage.setItem('spqr-lang',lang);renderHud();renderLeaders();const u=state.armies.find(a=>a.id===activeArmy&&a.owner===state.player)||reportedArmies(state,state.player).find(a=>a.id===activeArmy);if(u)showArmy(u);else if(activeBattle)showBattle(activeBattle);else if(activeFaction)showFaction(activeFaction,factionSection);else if(activeInfo?.type==='character')characterUI.show(activeInfo.id);else if(activeInfo?.type==='road')showRoad(activeInfo.name);else if(activeInfo?.type==='city')showCity(cities.find(c=>c.name===activeInfo.name));else if(activeInfo?.type==='region')showRegion(region(state,activeInfo.id));else if(activeInfo?.type==='resources')showResource(activeInfo.id);else if(activeInfo?.type==='help')openHelp();else if(document.querySelector('.faction-directory'))factionDirectory();tutorial.refresh()};
document.querySelector('#chronicle').onclick=()=>{activeInfo=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();inspect(t('chronicle'),lang==='zh'?'最近的回合结算与事件':'Recent turn summaries and events');const summaries=(state.turnSummaries||[]).slice(0,8).map(x=>`<article class="dispatch"><strong>${x.month}/${Math.abs(x.year)} · ${lang==='zh'?'国库':'Treasury'} ${x.delta.treasury>=0?'+':''}${x.delta.treasury} · ${lang==='zh'?'粮食':'Food'} ${x.delta.food>=0?'+':''}${x.delta.food}</strong>${x.movements.filter(m=>m.owner===state.player).map(m=>`<p>${esc(n(m.name))} → ${esc(n(m.to))}</p>`).join('')}${x.changes.map(c=>`<p>${esc(n(c.name))} → ${esc(n(c.owner))}</p>`).join('')}${x.events.map(e=>`<p>${esc(visibleLogText(e,lang))}</p>`).join('')}</article>`).join('');document.querySelector('#command-detail').innerHTML=`<div class="help-list">${summaries||state.log.slice(0,12).map(e=>`<p class="dispatch">${e.month}/${Math.abs(e.year)} · ${esc(visibleLogText(e,lang))}</p>`).join('')||t('empty')}</div>`};
renderHud();

document.querySelector('#capture').onclick=async()=>{const button=document.querySelector('#capture');button.disabled=true;status.style.display='none';try{if(!window.html2canvas){await new Promise((resolve,reject)=>{const script=document.createElement('script'),timer=setTimeout(()=>{script.remove();reject(Error('Screenshot library timed out'))},12000);script.src='https://unpkg.com/html2canvas@1.4.1/dist/html2canvas.min.js';script.onload=()=>{clearTimeout(timer);resolve()};script.onerror=()=>{clearTimeout(timer);script.remove();reject(Error('Screenshot library unavailable'))};document.head.append(script)})}const ready=await waitForMapIdle(map);const canvas=await html2canvas(document.body,{backgroundColor:'#17262a',scale:1,useCORS:true,logging:false});const link=document.createElement('a');link.download=`spqr-map-${canvas.width}x${canvas.height}.png`;link.href=canvas.toDataURL('image/png');let preview=document.querySelector('#capture-result');if(!preview){preview=document.createElement('img');preview.id='capture-result';preview.hidden=true;document.body.append(preview)}preview.src=link.href;link.click();if(!ready||tileErrors){status.textContent=lang==='zh'?'地图资源可能未全部加载，截图可能不完整。':'Some map data may not have loaded; the screenshot may be incomplete.';status.style.display='block'}}catch(e){status.textContent=lang==='zh'?'截图失败，请检查网络连接后重试。':'Screenshot failed; check the network connection and try again.';status.style.display='block';console.warn(e)}finally{button.disabled=false}};

if(new URLSearchParams(location.search).has('perf')){let count=0,start=performance.now();function sample(now){count++;if(now-start<3000)requestAnimationFrame(sample);else{document.body.dataset.perfFps=String(Math.round(count*1000/(now-start)));document.body.dataset.perfSeconds=String(((now-start)/1000).toFixed(1))}}requestAnimationFrame(sample)}

function saveSlot(action){const choice=document.querySelector('#save-slot').value;if(!['1','2','3'].includes(choice))return;const key=`spqr-save-${choice}`;if(action==='save'){localStorage.setItem(key,JSON.stringify(state));status.textContent=lang==='zh'?`已保存至栏位 ${choice}`:`Saved to slot ${choice}`;status.style.display='block';return}const raw=localStorage.getItem(key);if(!raw){status.textContent=lang==='zh'?'此存档栏为空。':'This slot is empty.';status.style.display='block';return}try{const saved=upgradeSave(JSON.parse(raw));if(!['caesar','senate'].includes(saved.player))throw Error('Not a Roman campaign');setPlaying(false);tutorial.stop();state=saved;activeInfo=null;activeFaction=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();battleMarkers.forEach(m=>m.remove());battleMarkers=[];renderArmies();renderHud();inspect(lang==='zh'?'存档已读取':'Campaign loaded',lang==='zh'?'已恢复战役状态。':'Campaign state restored.');status.style.display='none'}catch(e){status.textContent=lang==='zh'?'存档无法读取。':'Could not load this save.';status.style.display='block'}}
document.querySelector('#save').onclick=()=>saveSlot('save');document.querySelector('#load').onclick=()=>saveSlot('load');

document.querySelector('#map-mode').onchange=e=>{currentMapMode=e.target.value;updateControl();renderHud()};
document.querySelector('#objective-toggle').onclick=()=>{objectivesOpen=!objectivesOpen;renderHud()};

document.querySelector('#brief-toggle').onclick=()=>{const b=document.querySelector('.brief');b.classList.toggle('collapsed');document.querySelector('#brief-toggle').textContent=b.classList.contains('collapsed')?'›':'‹';document.querySelector('#brief-toggle').setAttribute('aria-expanded',String(!b.classList.contains('collapsed')))};

document.querySelector('#factions').onclick=factionDirectory;
function resourceHelp(id){
 const f=state.factions[state.player],owned=state.regions.filter(r=>r.owner===state.player),troops=state.armies.filter(a=>a.owner===state.player).reduce((x,a)=>x+a.men,0),rate={low:.65,normal:1,high:1.4}[f.tax],tax=Math.round(owned.reduce((v,r)=>v+r.tax*rate*r.loyalty/100,0)-troops/1100)+officeEffects(state,state.player).treasury,grain=Math.round(owned.reduce((v,r)=>v+r.food,0)-troops/1200-owned.length*2)+officeEffects(state,state.player).food,zh=lang==='zh';
 const info={treasury:zh?`国库 ${f.treasury}；按当前战区、忠诚度、税率、军费和行政任命估计每月 ${tax>=0?'+':''}${tax}。负债会降低稳定度和士气。`:`Treasury ${f.treasury}; estimated monthly change ${tax>=0?'+':''}${tax} from owned theaters, loyalty, tax, upkeep and administrative assignments. Debt reduces stability and morale.`,food:zh?`粮食 ${f.food}；按当前产量、战区、兵力和行政任命估计每月 ${grain>=0?'+':''}${grain}。低于20会削弱战斗力，负粮会造成损耗。`:`Food ${f.food}; estimated monthly change ${grain>=0?'+':''}${grain} from production, upkeep and administrative assignments. Below 20 weakens combat power; negative food causes losses.`,manpower:zh?`兵源 ${f.manpower.toLocaleString()}；当前每月恢复 ${owned.length*170}。征召一支军队需要3000兵源。`:`Manpower ${f.manpower.toLocaleString()}; currently gains ${owned.length*170} per month. Raising a force costs 3,000.`,stability:zh?`稳定度 ${f.stability}%。国库或粮食为负会降低稳定度；低于60且地方忠诚低于25时，缺少守军的战区可能叛乱。`:`Stability ${f.stability}%. Debt or food shortages reduce it. Below 60, an undefended theater below 25 loyalty may rebel.`,legitimacy:zh?`合法性 ${f.legitimacy}%。向其他势力宣战会降低5点；当前版本不把它作为胜负条件。`:`Legitimacy ${f.legitimacy}%. Declaring war costs five points; it is not currently a victory condition.`};return info[id]||'';
}
function showResource(id){activeInfo={type:'resources',id};activeFaction=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();inspect(lang==='zh'?'资源与政治':'RESOURCES & POLITICS',lang==='zh'?'每月变化根据当前战区和军队估算。':'Monthly changes are estimates based on current theaters and armies.');const panel=document.querySelector('#command-detail'),zh=lang==='zh',tax=state.factions[state.player].tax;panel.innerHTML=`<div class="help-list">${['treasury','food','manpower','stability','legitimacy'].map(k=>`<p>${esc(resourceHelp(k))}</p>`).join('')}</div><p class="battle-note">${zh?'税率影响收入与地方忠诚：低税每月恢复忠诚，高税每月降低忠诚。':'Tax rates affect income and theater loyalty: low tax restores loyalty, high tax reduces it.'}</p><div class="diplomacy-actions">${['low','normal','high'].map(level=>`<button data-tax="${level}" ${tax===level?'disabled':''}>${zh?({low:'低税',normal:'标准税',high:'高税'})[level]:({low:'LOW TAX',normal:'NORMAL TAX',high:'HIGH TAX'})[level]}</button>`).join('')}</div>`;panel.querySelectorAll('[data-tax]').forEach(b=>b.onclick=()=>{if(setTax(state,state.player,b.dataset.tax)){renderHud();showResource(id)}});emit('resources')}
document.querySelector('#resources-help').onclick=()=>showResource('treasury');
const helpEntries=[
 {kind:'game',en:'Move an army',zh:'如何行军',enBody:'Select your army, choose an adjacent destination, review the route and confirm. Advance months to finish travel. Crossing by sea costs 8 treasury.',zhBody:'选择己方军队，在相邻战区中选择目的地，检查路线后确认。推进月份完成行军；海上运输需要8国库。'},
 {kind:'game',en:'Battles and morale',zh:'战斗与士气',enBody:'Battles resolve when armies meet. Strength, morale, command skill, experience, food, terrain and forts influence the result. The report shows your forces and losses; exact enemy details remain unknown.',zhBody:'敌军遭遇时即时结算。兵力、士气、指挥、经验、粮食、地形和工事影响结果。战报显示己方兵力和伤亡；敌军确切数据仍未知。'},
 {kind:'game',en:'Food and supply',zh:'粮食与补给',enBody:'Food below 20 reduces combat power; negative food causes losses. The theater supply limit is currently informational and does not impose an extra penalty.',zhBody:'粮食低于20时战斗力下降；粮食为负会造成损耗。战区补给上限目前仅供参考，不额外施加惩罚。'},
 {kind:'game',en:'Recruitment and manpower',zh:'征召与兵源',enBody:'Select a city, open Manage theater, then recruit in a theater you control. Costs: 24 treasury, 3,000 manpower and 6 food.',zhBody:'选择城市，打开管理战区，在己方战区征召。消耗24国库、3000兵源和6粮食。'},
 {kind:'game',en:'Diplomacy and control',zh:'外交与控制',enBody:'Different powers may be at war, allied or at peace. Open Factions, choose a power and use diplomacy. Official inquiries are sent by letter and take months; no reply or refusal is possible.',zhBody:'各势力可能交战、结盟或和平。点击势力并选择国家即可进行外交。直接询问需要寄信，数月后可能收到答复、拒答或没有回信。'},
 {kind:'game',en:'Provincial loyalty and unrest',zh:'地方忠诚与叛乱',enBody:'Theater loyalty affects tax income. High taxes lower it; low taxes restore it. Below 25 loyalty and 60 stability, an undefended theater may rebel.',zhBody:'战区忠诚度影响税收。高税会降低忠诚度，低税可恢复。当忠诚低于25、稳定度低于60且没有守军时，战区可能叛乱。'},
 {kind:'game',en:'Turns, saving and objectives',zh:'回合、存档与目标',enBody:'Advance one month to resolve movement, economy, sieges and AI. The Chronicle records events. Select a save slot and press Save or Load. Click an objective for guidance; it will not issue orders.',zhBody:'推进一个月以结算行军、经济、围攻与AI行动。战报记录事件；选择存档栏后点击保存或读取。点击目标可查看指引，不会自动下令。'},
 {kind:'game',en:'Terrain relief and performance',zh:'地形光影与性能',enBody:'Use REL beside the zoom controls to toggle the hillshade overlay. Turning it off may reduce rendering load; satellite landcover, political control and gameplay remain. Your browser remembers the setting.',zhBody:'使用缩放按钮旁的“光影”切换山地阴影。关闭可能减轻渲染负担；卫星地表、政治控制和游戏规则仍然保留。浏览器会记住此设置。'},
 {kind:'game',en:'Appointing a commander',zh:'任命军队指挥官',enBody:'Select a stationary friendly army to appoint an available person in the same theater or relieve its commander. The former commander remains in the theater; the army’s base command rating stays unchanged, health affects combat, and no person may command two armies. Commanded battles increase that person’s power by 2% each, up to 10%, and the experience remains when reassigned.',zhBody:'选择未行动的己方军队，可任命同战区的可用己方人物，也可解除当前指挥。原指挥官留在战区；军队基础指挥评级不变，人物健康影响战斗，一人不能同时指挥两支军队。人物每指挥一场战斗可提高2%指挥战力，最多10%，转任后仍保留。'},
 {kind:'game',en:'Theater administrators',zh:'战区行政官',enBody:'Select a city in your controlled theater to appoint an eligible person located there for 5 treasury. The appointment adds one theater loyalty each quarter; dismissal is free. Health, loyalty, availability and control determine whether the assignment continues. The role is a game abstraction, not a historical city office or proof of presence in that city. Foreign local authorities remain unknown.',zhBody:'选择己方控制战区中的城市，可以花费5国库任命位于该战区的合格人物；任职期间每季度增加该战区1点忠诚，解除免费。健康、忠诚、人员状态或控制权变化可能使其卸任。这是游戏中的战区职务，不是历史城市官职，也不代表此人就在城内；外国地方负责人未知。'},
 {kind:'game',en:'Administrative assignments',zh:'行政任命',control:'#factions',enBody:'Open your faction to appoint finance, supply and administration officers. Appointment costs 5 treasury; dismissal is free. Capable friendly people need at least 40 loyalty and cannot command an army, hold another assignment or travel independently while appointed. An unavailable official loses the assignment before the next monthly economy.',zhBody:'打开己方势力，可任命财务、粮秣和政务专员。任命消耗5国库，解除免费。人选必须有至少40忠诚、能够履职，不能指挥军队或兼任其他职位；任职期间不能独立旅行。无法履职的官员会在下次月度经济结算前卸任。'},
 {kind:'game',en:'Commander loyalty',zh:'将领忠诚',control:'#factions',enBody:'Friendly character profiles have simulated loyalty, separate from theater loyalty. Low faction stability reduces personal loyalty each year. During the Roman civil war, a non-leading officer without an army may defect when loyalty reaches 20 or below.',zhBody:'己方人物档案中的模拟忠诚度与战区忠诚度不同。势力稳定度低时，个人忠诚每年下降。罗马内战期间，忠诚不高于20、未领导派系且未指挥军队的官员可能倒戈。'},
 {kind:'game',en:'Reports and uncertainty',zh:'情报报告与不确定性',control:'#factions',enBody:'Open Factions, choose another power, then Letters & Intelligence. Reports show source, observation date, reliability and confidence. Political stability and possible succession plans can be investigated; no identifiable names do not prove absence or erase the last named leader report, and no information does not prove no plan exists. Conflicting reports remain visible; old reports may be wrong. Your save contains the true simulated world and is not a secrecy boundary.',zhBody:'打开“势力”，选择其他势力，再打开“书信与情报”。报告显示来源、观察日期、可靠性和可信度；可以调查政治稳定度和可能的继任安排；没有可核实的姓名不代表无人执政或没有竞争者，也不会覆盖旧领袖报告；没有消息不等于没有计划。冲突报告会保留，旧报告可能错误。本地存档包含真实模拟状态，并非保密边界。'},
 {kind:'game',en:'Letters and direct questions',zh:'书信与直接询问',control:'#factions',enBody:'A direct inquiry costs 3 treasury and normally takes 2–5 months. A letter or reply may be lost; war increases the risk on the return journey. The court may refuse, and its answer is unverified. Other diplomatic buttons currently resolve immediately.',zhBody:'直接询问消耗3国库，通常需要2至5个月。信件或回信可能遗失，交战会增加返程风险；对方可能拒答，官方答复未经独立核实。其他外交按钮目前即时结算。'},
 {kind:'game',en:'Spies, captured agents and release',zh:'间谍、被俘与释放',control:'#factions',enBody:'A spy costs 12 treasury and takes 4 months; discovery or capture harms relations. Each faction has three agents: missions and captivity occupy capacity. A release letter costs 8 treasury and takes about 4 months; it may be refused or unanswered.',zhBody:'派遣间谍消耗12国库、需要4个月；被发现或被捕会损害关系。每个势力有3名情报人员，执行任务或被俘会占用人手。请求释放需8国库，约4个月后可能被拒或没有回信。'},
 {kind:'game',en:'Personal meetings and travel',zh:'人物旅行与个人会面',control:'#factions',enBody:'Open your faction and select an independent character to plan a journey. Army commanders and seriously ill characters cannot travel independently; wounds and frailty slow each leg. A personal audience with a reported leader, claimant or commander costs 3 treasury and takes 2 months; both people must actually be in the same theater and may not meet. Reports can be stale or wrong. Trust and relations affect acceptance; a successful meeting improves relations by 3. For 36 months, personal trust can add up to 10 toward alliance eligibility, subject to other constraints. A known contact can improve a later claimant support offer, but letters may still be lost or refused.',zhBody:'打开己方势力并选择独立人物以规划旅行。随军指挥官和重病人物不能单独出行，受伤或衰弱会拖慢每段行程。可向已报告的领袖、竞争者或指挥官请求个人会面，消耗3国库、需要2个月；双方须实际位于同一战区，也可能无法会面。报告可能过时或错误。已有信任及势力关系影响接受意愿；成功会面使双方关系提高3；36个月内，个人信任还能为结盟条件提供最多10点加成，但不能排除其他阻碍。可让有信任的人帮助联系竞争者，但书信仍可能丢失或被拒。'},
 {kind:'game',en:'Character health and succession',zh:'人物健康与继任',control:'#factions',enBody:'Game health, wounds and illness are simulated, not historical diagnoses. Health changes are checked monthly; illness and wounds can improve or worsen, including recovery from serious illness. Wounds, service and shortages affect risk. A seriously ill or dying commander is relieved before movement or battle; an unnamed officer takes over while the person remains in the last theater. Political authority is handled separately. In your faction panel designate a possible successor for 5 treasury; when a leader is incapacitated, changing the acting deputy costs 5. A living co-leader remains in office. A commander missing after defeat may regain contact after three months if the faction controls a theater; health events pause while missing.',zhBody:'健康、战伤和疾病是游戏模拟，并非历史诊断。健康每月结算，疾病与战伤可能好转或恶化，重病也有机会康复。战伤、军旅与粮食短缺会影响风险。重病或垂危的将领会在行军或战斗前卸下军职，由未具名军官接替；人物留在原战区，政治领导另行处理。在己方势力面板可用5国库指定可能的继任者；领导人无法履职时，更换代行官员需5国库。仍在任的共同领导者不会被替换。战败后失联的指挥官如仍有己方战区，三个月后可重新取得联系；失联期间暂停健康事件。'},
 {kind:'game',en:'Dynastic rivalries',zh:'王朝竞争',control:'#factions',enBody:'In this alternate-history simulation, a disaffected Pacorus can challenge the Parthian court when instability or the ruler’s incapacity creates an opening. A settlement can end the challenge without joint rule; a takeover or contested vacancy can also occur. Every three months an unresolved dispute reduces the affected court’s stability by 1 and treasury by 3. Foreign players do not see these hidden changes directly: investigate reports before offering support. Letters can be refused, lost or unanswered; reports can be wrong.',zhBody:'在架空模拟中，不满的帕科鲁斯可能在帕提亚政局不稳或君主无法履职时挑战宫廷。和解可以结束争议而不产生共同统治；也可能发生夺权或继承空缺。争议未解决时，每三个月使相关宫廷的稳定度降低1、国库减少3。外国玩家不会直接看到这些隐蔽变化，可先调查报告再提供支持；书信可能被拒、遗失或得不到答复，报告也可能有误。'},
 {kind:'game',en:'Internal plots and reassurance',zh:'内部阴谋与安抚',control:'#factions',enBody:'Political plots are simulated possibilities, not historical claims. When loyalty and stability are low, a disaffected officer may challenge leadership. Simulated ambition and trust with the current leader influence plot risk; supporting a successor raises ambition and leader trust by 5 each, but ambition alone does not prove a plot. Your faction panel offers a three-month internal investigation for 8 treasury and an agent; reports may be wrong. Reassure any eligible friendly person for 8 treasury to raise loyalty by 15 and trust with a current leader by 5 if available. A report or reassurance does not prove guilt.',zhBody:'内部阴谋是游戏可能发生的事件，并非历史事实。当忠诚和稳定度低时，心怀不满的官员可能挑战领导。模拟野心和与在任领袖的信任会影响阴谋风险；支持继任人选使其野心及双方信任各增加5，但野心高本身不证明参与阴谋。己方势力面板可花费8国库和一名情报人员，调查3个月；报告可能有误。也可花费8国库安抚任意合适的己方人物，忠诚提高15；若有在任领袖，双方信任也提高5。报告或安抚均不证明其有罪。'},
 {kind:'game',en:'Acting authority intelligence',zh:'代行政务情报',control:'#factions',enBody:'Investigate acting authority with spies, envoys or travelers, or request an ally’s existing report. Reports may name a regent, acting commander or co-ruler, but can be wrong, withheld or outdated. Open a reported portrait to inspect that person; their current health and location remain unknown. Comparing independent sources can reveal disagreement.',zhBody:'可派间谍、使者或商旅调查代行政务，也可请求盟友转交已有报告。报告可能提到摄政者、临时指挥者或共同统治者，也可能有误、被隐瞒或已经过期。点击报告中的肖像可查看人物档案；其当前健康和位置仍然未知。比较独立来源可发现分歧。'},
 {kind:'game',en:'Covert contacts',zh:'秘密政治接触',control:'#factions',enBody:'A Roman faction may send an offer to an Egyptian claimant it has heard about. A spy investigating Egypt can report a recent accepted offer by the other Roman faction. Reports are unverified and may be wrong; no reliable information does not prove that no contact exists. These are simulated contacts, not historical claims or formal alliances.',zhBody:'罗马派系可以向自己听闻的埃及竞争者寄出支持提议。派间谍调查埃及，可能查到另一罗马派系最近获得接受的提议。报告未经核实，可能有误；没有可靠消息不代表不存在接触。这些是游戏模拟的接触，并非历史断言或正式同盟。'},
 {kind:'game',en:'Checking intelligence reports',zh:'核查情报报告',control:'#factions',enBody:'In a foreign faction’s Intelligence tab, open Why this confidence to compare supporting and conflicting source families. Use Check this report to select its subject and, for health, the reported person. Then choose and confirm a mission. Selecting a report costs nothing. Repeating or forwarding the same source is not independent corroboration; another source can also be wrong. A list can be incomplete; a source may claim completeness without proving it. Different named rulers or claimants are compatible unless a claimed complete list excludes someone. Reports from different observation months may describe a change and do not confirm or contradict a claim at the same time. Coordinate missions to compare observations from the same month. Partially overlapping age estimates are compatible but do not verify an exact range. Confidence is recalculated as evidence expires each month.',zhBody:'在外国势力的情报页面展开“查看判断依据”，可比较支持与冲突的来源。点击“核查此报告”，可选中对应调查内容；健康报告也会选中已报告的人物。然后选择并确认行动。选择报告不收费。重复或转交同一来源不构成独立核实，其他来源也可能有误。人名名单可能不完整；来源声称完整也不等于事实。不同人名可能并存，除非声称完整的名单排除了对方。不同观察月份的报告可能反映局势变化，不算同时核实或冲突；可协调行动，使不同来源在同一月观察。部分重叠的年龄估计彼此相容，但不能证明完整区间完全一致。每月会依据尚未过期的证据重新计算可信度。'},
 {kind:'game',en:'Reported commanders',zh:'指挥官目击报告',control:'#factions',enBody:'Frontier observations may identify a foreign army’s commander. The dated report can be opened from that army and used to select a person for health inquiries or an audience. It can become outdated when the army moves or command changes; an unseen change is not automatically revealed.',zhBody:'前线目击可能识别外国军队的指挥官。可从军队查看带日期的报告，并以此人物作为健康调查或会面对象。军队移动或更换指挥官后，旧报告可能过时；未被目击的变化不会自动公开。'},
 {kind:'game',en:'What rival commanders know',zh:'对手掌握的情报',control:'#factions',enBody:'Computer factions estimate foreign strength from their own reports and recent sightings, using a rough assumption when evidence is missing. They may make mistaken decisions. A numerical report gradually loses influence after two years; old observations are not fresh confirmation.',zhBody:'电脑势力依据自己的报告和近期目击估计外国兵力；缺少证据时只能粗略推测，因此也可能判断错误。兵力报告在两年后逐渐失去影响，旧目击不等于新证实。'},
 {kind:'game',en:'Supporting a reported claimant',zh:'支持已报告的竞争者',control:'#factions',enBody:'In Egypt’s or Parthia’s Letters & Intelligence panel, investigate claimants before making an offer. It costs 10 treasury and takes 4 months; it may be accepted, refused or unanswered. Acceptance can increase the claimant’s chance of taking power and reduces court relations by 10. Reports can be outdated or false.',zhBody:'在埃及或帕提亚的“书信与情报”中先调查竞争者，再寄出支持提议。费用10国库、需要4个月，可能被接受、拒绝或没有回信。接受可能增加竞争者夺权机会，并使宫廷关系降低10；报告也可能过时或错误。'},
 {kind:'game',en:'Research and construction',zh:'研究与建设',enBody:'Research and construction are not implemented in this campaign slice.',zhBody:'当前战役片段尚未实现研究与建设。'},
 {kind:'history',en:'Who was Julius Caesar?',zh:'尤利乌斯·凯撒是谁？',enBody:'Julius Caesar was a Roman general and politician. In 49 BCE his crossing of the Rubicon preceded the civil war against Pompey and the Senate.',zhBody:'尤利乌斯·凯撒是罗马将领和政治人物。公元前49年，他越过卢比孔河，随后与庞培和元老院爆发内战。'},
 {kind:'history',en:'Who was Pompey?',zh:'庞培是谁？',enBody:'Gnaeus Pompeius Magnus was a Roman commander and politician who opposed Caesar during the civil war.',zhBody:'格奈乌斯·庞培是罗马将领和政治人物，在内战中与凯撒对立。'}
];
for(const c of Object.values(CHARACTER_CATALOG))helpEntries.push({kind:'history',en:c.name[0],zh:c.name[1],enBody:(HISTORICAL_BIO[Object.keys(CHARACTER_CATALOG).find(id=>CHARACTER_CATALOG[id]===c)]?.[0]||c.role[0])+' Simulated health and later events are fictional.',zhBody:(HISTORICAL_BIO[Object.keys(CHARACTER_CATALOG).find(id=>CHARACTER_CATALOG[id]===c)]?.[1]||c.role[1])+' 游戏中的健康和之后的事件属于模拟。',source:c.source});
function openHelp(){activeInfo={type:'help'};activeFaction=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();const zh=lang==='zh';inspect(zh?'游戏帮助与历史':'GAME HELP & HISTORY',zh?'选择分类或搜索；游戏规则与历史知识分开。':'Choose a category or search; gameplay and history are separate.');const target=document.querySelector('#command-detail');target.innerHTML=`<div class="diplomacy-tabs"><button id="help-game">${zh?'游戏指南':'GAMEPLAY GUIDE'}</button><button id="help-history">${zh?'历史百科':'HISTORICAL ENCYCLOPEDIA'}</button></div><input id="help-search" type="search" aria-label="${zh?'搜索帮助':'Search help'}" placeholder="${zh?'搜索帮助':'Search help'}"><div id="help-results" class="help-list"></div>`;const input=target.querySelector('#help-search'),out=target.querySelector('#help-results');let category='game';const update=()=>{const q=input.value.trim().toLowerCase();out.innerHTML=helpEntries.filter(x=>x.kind===category&&[x.en,x.zh,x.enBody,x.zhBody].some(v=>v.toLowerCase().includes(q))).map(x=>{const index=helpEntries.indexOf(x);return `<article><strong>${esc(zh?x.zh:x.en)}</strong><p>${esc(zh?x.zhBody:x.enBody)}</p>${x.kind==='game'?`<button data-help-locate="${index}">${zh?'指出相关控件':'HIGHLIGHT CONTROL'}</button>`:''}${x.source?`<a href="${esc(x.source)}" target="_blank" rel="noreferrer">${zh?'查看历史资料':'Historical source'}</a>`:''}</article>`}).join('')||`<p>${zh?'没有匹配的条目。':'No matching entries.'}</p>`;out.querySelectorAll('[data-help-locate]').forEach(b=>b.onclick=()=>{const entry=helpEntries[Number(b.dataset.helpLocate)],selector=entry.control|| (entry.en.includes('Recruitment')?'#map [data-city="MEDIOLANUM"]':entry.en.includes('Diplomacy')?'#factions':entry.en.includes('Turns')?'#advance':entry.en.includes('Food')?'#resources-help':entry.en.includes('Battles')?'#recent-battle':entry.en.includes('Move')?'#map [data-army="xiii"]':'#help');const el=document.querySelector(selector);if(!el){b.textContent=zh?'当前控件尚未出现':'Control is not available yet';return}el.classList.add('guide-highlight');el.scrollIntoView({block:'nearest',inline:'nearest'});setTimeout(()=>el.classList.remove('guide-highlight'),5000)})};input.oninput=update;target.querySelector('#help-game').onclick=()=>{category='game';update()};target.querySelector('#help-history').onclick=()=>{category='history';update()};update()}
document.querySelector('#help').onclick=openHelp;
const tutorial=createTutorial({skipInitial:!!received,language:()=>lang,onMode:()=>{},onReset:(mode,faction='caesar')=>{setPlaying(false);state=newGame(faction);state.difficulty=mode;if(mode==='beginner'){state.factions[faction].treasury+=40;state.factions[faction].food+=30;state.factions[faction].manpower+=3000;state.factions[faction].stability=Math.min(100,state.factions[faction].stability+5)}activeInfo=null;activeFaction=null;activeArmy=null;activeBattle=null;previewDestination='';clearReach();battleMarkers.forEach(m=>m.remove());battleMarkers=[];renderArmies();renderHud();inspect(lang==='zh'?'选择军队':'Select a command',lang==='zh'?'点击军团或城市查看详情。':'Select an army or city to inspect it.');map.flyTo({center:[12.4,43.2],zoom:5.45})}});
